import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

class WelcomeBackLogo extends StatelessWidget {
  final double height;
  final BoxFit fit;

  const WelcomeBackLogo({
    super.key,
    this.height = 70,
    this.fit = BoxFit.contain,
  });

  static final Uint8List _logoBytes = base64Decode('');

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      _logoBytes,
      height: height,
      fit: fit,
      errorBuilder: (context, error, stackTrace) => Image.asset(
        'assets/images/welcome_back.png',
        height: height,
        fit: fit,
      ),
    );
  }
}
